window.ScripturaLexicons.BDAG_PART_0295 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0295-01\" data-source=\"BDAG\" data-search=\"πόρνη, ης, ἡ substantivo feminino prostituta, entidade política hostil a Deus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πόρνη, ης, ἡ</td><td>substantivo feminino</td><td>prostituta, entidade política hostil a Deus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0295-02\" data-source=\"BDAG\" data-search=\"πόρνος, ου, ὁ substantivo masculino fornicador, imoral sexual BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πόρνος, ου, ὁ</td><td>substantivo masculino</td><td>fornicador, imoral sexual</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0295-03\" data-source=\"BDAG\" data-search=\"πόρρω advérbio longe, distante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πόρρω</td><td>advérbio</td><td>longe, distante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0295-04\" data-source=\"BDAG\" data-search=\"πόρρωθεν advérbio de longe, à distância BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πόρρωθεν</td><td>advérbio</td><td>de longe, à distância</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0295-05\" data-source=\"BDAG\" data-search=\"πορρώτερον/πορρωτέρω remissão ver πόρρω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πορρώτερον/πορρωτέρω</td><td>remissão</td><td>ver πόρρω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0295-06\" data-source=\"BDAG\" data-search=\"πορφύρα, ας, ἡ substantivo feminino púrpura, tecido ou veste de púrpura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πορφύρα, ας, ἡ</td><td>substantivo feminino</td><td>púrpura, tecido ou veste de púrpura</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0295-07\" data-source=\"BDAG\" data-search=\"πορφυρόπωλις, ιδος, ἡ substantivo feminino vendedora de púrpura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πορφυρόπωλις, ιδος, ἡ</td><td>substantivo feminino</td><td>vendedora de púrpura</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0295-08\" data-source=\"BDAG\" data-search=\"πορφυροῦς, ᾶ, οῦν adjetivo de cor púrpura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πορφυροῦς, ᾶ, οῦν</td><td>adjetivo</td><td>de cor púrpura</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0295-09\" data-source=\"BDAG\" data-search=\"ποσάκις advérbio quantas vezes?, com que frequência? BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποσάκις</td><td>advérbio</td><td>quantas vezes?, com que frequência?</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0295-10\" data-source=\"BDAG\" data-search=\"πόσις, εως, ἡ substantivo feminino ato de beber, bebida BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πόσις, εως, ἡ</td><td>substantivo feminino</td><td>ato de beber, bebida</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0295-11\" data-source=\"BDAG\" data-search=\"πόσος, η, ον pronome interrogativo quanto?, quantos?, quão grande? BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πόσος, η, ον</td><td>pronome interrogativo</td><td>quanto?, quantos?, quão grande?</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0295-12\" data-source=\"BDAG\" data-search=\"ποσότης, ητος, ἡ substantivo feminino quantidade, montante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποσότης, ητος, ἡ</td><td>substantivo feminino</td><td>quantidade, montante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0295-13\" data-source=\"BDAG\" data-search=\"ποταμός, οῦ, ὁ substantivo masculino rio, corrente, torrente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποταμός, οῦ, ὁ</td><td>substantivo masculino</td><td>rio, corrente, torrente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0295-14\" data-source=\"BDAG\" data-search=\"ποταμοφόρητος, ον adjetivo arrastado por um rio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποταμοφόρητος, ον</td><td>adjetivo</td><td>arrastado por um rio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0295-15\" data-source=\"BDAG\" data-search=\"ποταπός, ή, όν adjetivo interrogativo de que espécie?, quão grande? BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποταπός, ή, όν</td><td>adjetivo interrogativo</td><td>de que espécie?, quão grande?</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0295-16\" data-source=\"BDAG\" data-search=\"ποταπῶς advérbio de que maneira?, como? BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποταπῶς</td><td>advérbio</td><td>de que maneira?, como?</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0295-17\" data-source=\"BDAG\" data-search=\"πότε advérbio interrogativo quando?, até quando? BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πότε</td><td>advérbio interrogativo</td><td>quando?, até quando?</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0295-18\" data-source=\"BDAG\" data-search=\"ποτέ partícula enclítica outrora, alguma vez, finalmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποτέ</td><td>partícula enclítica</td><td>outrora, alguma vez, finalmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0295-19\" data-source=\"BDAG\" data-search=\"πότερος, α, ον pronome interrogativo qual dos dois?, se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πότερος, α, ον</td><td>pronome interrogativo</td><td>qual dos dois?, se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0295-20\" data-source=\"BDAG\" data-search=\"ποτήριον, ου, τό substantivo neutro copo, cálice, destino, sofrimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποτήριον, ου, τό</td><td>substantivo neutro</td><td>copo, cálice, destino, sofrimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0295-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πόρνη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πόρνη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (cf. <span class=\"greek\">πέρνημι</span> ‘exportar para venda’ [v. Schwyzer I 362], como no caso de mulheres cativas exportadas para a escravidão Hom. et al.) (Alcaeus, Hipponax; Aristoph., e X., Mem. 1, 5, 4; PSI 352, 4 [254/253 a.C.]; POxy 528, 18 [II d.C.]; BGU 1024 VI, 4; LXX; PsSol 2:11; TestLevi 14:5, 6; Philo, Just.; Tat. 34, 2; empréstimo no vocabulário rabínico) ‘prostituta’.</p><p class=\"entry-text\">① Mulher que mantém relações sexuais mediante remuneração, prostituta, meretriz, lit. (desde Alcaeus 109 + 110, 26 D.2 [115 Fgm. 3b 26 L-P.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:30</a> (cf. Pr 29:3; Test Levi 14:5 <span class=\"greek\">μετὰ</span> <span class=\"greek\">πορνῶν</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:15</a>. Acerca de Raabe (Josh 2:1; 6:17, 23, 25) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.31\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:25</a>; 1 Cl 12:1 (uma <span class=\"greek\">πόρνη</span> recompensada por um salvamento também em Neanthes [200 a.C.]: 84 Fgm. 9 Jac.). Com publicanos, como a classe mais baixa de pessoas, moralmente falando <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:31f</a>. Com flautistas do sexo feminino Ox 36. <span class=\"greek\">κολλᾶσθαι</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">π</span>. ter relações com uma prostituta (Sir 19:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:16</a>.</p><p class=\"entry-text\">② Entidade política hostil a Deus, prostituta, meretriz, extensão fig. de 1 (v. <span class=\"greek\">πορνεία</span> e <span class=\"greek\">πορνεύω</span>; Is 1:21; 23:15f; Jer 3:3; Ezk 16:30f, 35), como designação de um governo hostil a Deus e ao povo de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:15f</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">πόρνη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">μεγάλη</span> v. 1; 19:2. <span class=\"greek\">Βαβυλὼν</span> (v. esse lema) <span class=\"greek\">ἡ</span> <span class=\"greek\">μεγάλη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">μήτηρ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πορνῶν</span> 17:5 (a menos que se deva ler o masc. <span class=\"greek\">πόρνων</span>, v. artigo seguinte).—Quanto à mulher sentada sobre a besta, cf. Cebes 5, 1, uma mulher belamente adornada, sentada em um trono. Ela é chamada <span class=\"greek\">Ἀπάτη</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">χειρὶ</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">ποτήριόν</span> <span class=\"greek\">τι</span>, do qual dá de beber aos homens (<span class=\"greek\">ποτίζει</span> Cebes 5, 2 como <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:8</a>), a fim de desencaminhá-los (<span class=\"greek\">πλανάω</span> como <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.23\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:23</a>).—B. 1368. RAC III 1149–1212. DELG s.v. <span class=\"greek\">πέρνημι</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0295-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πόρνος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πόρνος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (cf. <span class=\"greek\">πόρνη</span>; Aristoph., X.+ no sentido de ‘meretriz masculino/prostituto’ e termos afins; Sir 23:17; Philo, Leg. All. 8; Just.; Tat. 34, 3)</p><p class=\"entry-text\">① Aquele que pratica imoralidade sexual, fornicador <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:9</a>, 11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:5</a>, se acentuado como masc. (em N.27 como fem.; v. aparato em Tdf. e nas primeiras edições de Nestle, inclusive a 25ª ed.), mas v. também 2. <span class=\"greek\">οἱ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">τούτου</span> as pessoas (sexualmente) imorais deste mundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:10</a>. Com outros pecadores <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:8</a>; 22:15. Distinguido de um adúltero <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:4</a>. Excluído do Reino de Deus, juntamente com outros culpados de pecados graves <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:9</a> (=Pol 5:3).</p><p class=\"entry-text\">② Entidade política hostil a Deus, fornicador, extensão fig. de 1: <span class=\"greek\">ἡ</span> <span class=\"greek\">μητὴρ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πόρνων</span> mãe dos fornicadores <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:5</a> v.l., v. 1.—RBorger TRu 52, ’87, 48–50.—DELG s.v. <span class=\"greek\">πέρνημι</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0295-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πόρρω</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πόρρω</span> adv. (a forma át. [=<span class=\"greek\">πόρσω</span>, cf. <span class=\"greek\">πρόσω</span> no mesmo sentido]; Pla., X.+; LXX; En; EpArist 31; Just., D. 10, 2; Tat.—Thackeray p. 123; B-D-F §34, 2), relativo a uma posição relativamente distante, longe.</p><p class=\"entry-text\">ⓐ Empregado como adv. 1 Cl 3:4; Hv 3, 6, 1. <span class=\"greek\">π</span>. <span class=\"greek\">εἶναι</span> estar longe (B-D-F §434, 1; Rob. 546) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:32</a>. <span class=\"greek\">π</span>. <span class=\"greek\">ἀπό</span> (En 32:4; Jos., Vi. 281): <span class=\"greek\">π</span>. <span class=\"greek\">γίνεσθαι</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> estar ou permanecer longe de alguém ou algo, fig. (cf. Bar 3:21) 1 Cl 23:3; 30:3 (alguns colocariam em b); 39:9 (Job 5:4). <span class=\"greek\">π</span>. <span class=\"greek\">ἀπέχειν</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> estar muito afastado de alguém, fig. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:6</a>; 1 Cl 15:2; 2 Cl 3:5 (todos os quatro Is 29:13).</p><p class=\"entry-text\">ⓑ Empregado como prep. com gen. (Isocr., Ep. 6, 13 <span class=\"greek\">κινδύνων</span> <span class=\"greek\">π</span>.; <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 17, 3; Ael. Aristid. 28, 103 K.=49 p. 525 D.: <span class=\"greek\">π</span>. <span class=\"greek\">θεῶν</span>; Philo, Op. M. 63; Jos., Ant. 7, 71, Vi. 167; Just., D. 10, 2; Tat. 15, 2) <span class=\"greek\">ὧν</span> <span class=\"greek\">μακρὰν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πόρρω</span> <span class=\"greek\">πραΰτης</span> B 20:2. V. a para 1Cl 30:3.</p><p class=\"entry-text\">ⓒ Como comp. do adv. temos no texto de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:28</a> <span class=\"greek\">πορρώτερον</span> (Aristot. et al.), e como v.l. <span class=\"greek\">πορρωτέρω</span> (X., Pla.; Jos., Bell. 4, 108, Vi. 326.—Thumb 77): <span class=\"greek\">πορρ</span>. <span class=\"greek\">πορεύεσθαι</span> ir mais longe.—B. 868. DELG s.v. <span class=\"greek\">πόρσω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0295-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πόρρωθεν</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πόρρωθεν</span> adv. (v. <span class=\"greek\">πόρρω</span>; Pla. et al.; LXX; KDieterich, Untersuchungen zur Gesch. der griech. Sprache 1898, 183f), relativo a uma posição como ponto de referência para determinar algo como distante, de longe (Aen. Tact. 540; 1199; Diod S 1, 83, 4; Jos., Bell. 3, 113; 4, 157, Ant. 3, 9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:13</a>. Com substituição de um conceito por outro, de longe=à distância (Herodian 2, 6, 13 <span class=\"greek\">π</span>. <span class=\"greek\">ἑστῶτες</span>) <span class=\"greek\">οἳ</span> <span class=\"greek\">ἔστησαν</span> <span class=\"greek\">πόρρωθεν</span> que ficaram à distância (<span class=\"greek\">ἵστημι</span> B 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:12</a> (Aesop, Fab. 1 P.=5 H.; 3 Ch.; 1 H-H. <span class=\"greek\">πόρρωθεν</span> <span class=\"greek\">στᾶσα</span>). <span class=\"greek\">οἱ</span> <span class=\"greek\">πόρρωθεν</span> os que estão à distância (Jos., Bell. 3, 394) B 9:1 (Is 33:13).—DELG s.v. <span class=\"greek\">πόρσω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0295-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πορρώτερον/πορρωτέρω</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πορρώτερον</span>/<span class=\"greek\">πορρωτέρω</span> v. <span class=\"greek\">πόρρω</span>, fim.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0295-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πορφύρα, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πορφύρα</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (Aeschyl., Hdt.et al.; inscrições, papiros, LXX; TestAbr A 4 p. 80, 21 [Stone p. 8]; TestLevi 8:7; JosAs, EpArist; Philo, Congr. Erud. Gr. 117; Jos., Bell. 6, 390; empréstimo no vocabulário rabínico), o molusco da púrpura (um molusco com concha, múrex), depois um corante púrpura obtido dele, finalmente o tecido, vestuário etc. Em nossa literatura somente no último sentido mencionado (assim Aeschyl. et al.; Aristot., Polyb., Lucian; Jos., Ant. 8, 185; EpArist 320; LXX), púrpura (tecido), com <span class=\"greek\">βύσσος</span> (v. esse lema) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:19</a>; GJs 10:(2), duas vezes com <span class=\"greek\">κόκκινον</span> (v. o papiro Bodmer e a ed. de deStrycker acerca deste texto controvertido); 12:1. <span class=\"greek\">ἔλαβεν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">π</span>. … <span class=\"greek\">καὶ</span> <span class=\"greek\">ἧλκεν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">π</span>. 11:1. Veste de púrpura (Appian, Liby. 66, 297) com <span class=\"greek\">τὸ</span> <span class=\"greek\">βύσσινον</span> (v. <span class=\"greek\">βύσσινος</span> e cf. JosAs 5:6 <span class=\"greek\">πορφύρα</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">βύσσου</span> <span class=\"greek\">χρυσοϋφής</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:12</a>. Cf. 17:4 v.l. (com <span class=\"greek\">κόκκινον</span>). Acerca da veste vermelha que os soldados puseram em Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:17</a>, 20; GPt 3:7 (Appian, Bell. Civ. 2, 150 o manto do soldado romano é chamado <span class=\"greek\">ἡ</span> <span class=\"greek\">πορφύρα</span>; v. <span class=\"greek\">χλαμύς</span>.—Dio Chrys. 4, 71 e Jos., Ant. 11, 256; 257 acerca de uma veste real de púrpura; cf. 1 Macc 10:62).—Bibliografia, v. <span class=\"greek\">κόκκινος</span>, também RGradwohl, Die Farben im AT, Beih. ZAW 83, ’63, 66–73 e bibliografia; Pauly-W. XXIII 2200–220; Kl. Pauly IV 1243f; BHHW III 1532f; ABD s.v. ‘Purple’ (V 557–60) e ‘Zoology (Animal Profiles)’ (VI 1149f); New Docs 2, 25–27 (bibliografia); CHemer, New Docs 3, 53–55; também Hemer, Acts 114; HStulz, Die Farbe Purpur im frühen Griechentum ’90.—Schmidt, Syn. III 44–51. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0295-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πορφυρόπωλις, ιδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πορφυρόπωλις</span>, <span class=\"greek\">ιδος</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πωλέω</span>; o fem., encontrado em CIG 2519 [onde é restaurado, mas certamente correto], e PFlor 71, 641 [IV d.C.] de <span class=\"greek\">πορφυροπώλης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> [p. ex. IHierapJ 156]=comerciante de tecido de púrpura [de lã] [v. WSchmidt, Forschungen aus dem Gebiete des Altertums I 1842, 163ff]), comerciante de tecidos de púrpura, acerca de Lídia de Tiatira (v. <span class=\"greek\">Θυάτιρα</span>) em Filipos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:14</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0295-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πορφυροῦς, ᾶ, οῦν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πορφυροῦς</span>, <span class=\"greek\">ᾶ</span>, <span class=\"greek\">οῦν</span> (a forma preferida no grego ático, também na LXX, Joseph. [p. ex. Bell. 7, 124, Ant. 10, 235; Schmidt 492], em lugar do mais antigo [Hom. et al.; SIG 999, 5; SibOr 3, 659] <span class=\"greek\">πορφύρεος</span>, <span class=\"greek\">έα</span>, <span class=\"greek\">εον</span>), de cor púrpura <span class=\"greek\">ἱμάτιον</span> <span class=\"greek\">πορφυροῦν</span> (Diod S 2, 59, 4; Num 4:14; EpJer 11; cf. PRyl 151, 14 [40 d.C.] <span class=\"greek\">χιτῶνα</span> <span class=\"greek\">πορφυροῦν</span>) um manto de púrpura <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:2</a>, 5. Substantivado <span class=\"greek\">τὸ</span> <span class=\"greek\">πορφυροῦν</span> (isto é, <span class=\"greek\">ἱμάτιον</span>) vestuário de púrpura com <span class=\"greek\">κόκκινον</span> (v. <span class=\"greek\">κόκκινος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:4</a>; cf. 18:16.—GEuler, <span class=\"greek\">πορφυροῦς</span>, purpureus, Progr. Weilburg 1907.—DELG s.v. <span class=\"greek\">πορφύρα</span>. M-M s.v. <span class=\"greek\">πορφύρεος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0295-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποσάκις</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποσάκις</span> (sobre a formação, v. Schwyzer I 597f) adv. Pla. et al.; POxy 528, 24; LXX; TestJos 3:1), referência a um número de momentos relacionados, em pergunta ou exclamação, quantas vezes? com que frequência? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:21</a>; 23:37; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:34</a>; AcPl Ha 8, 10.—V. DELG s.v. <span class=\"greek\">πο</span>-e-<span class=\"greek\">κις</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0295-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πόσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πόσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πίνω</span>; Hom. et al.; BGU 1191, 3 [I a.C.]; O. Theb 3, 1; Ath 22, 2), em nossa literatura sempre com <span class=\"greek\">βρῶσις</span> (como Da 1:10; TestAbr B 13 p. 117, 23 [Stone p. 82]; <span class=\"greek\">τὰς</span> <span class=\"greek\">τρυφὰς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">π</span>. ApcSed 11:11 p. 134, 27 Ja.).</p><p class=\"entry-text\">① Ato de beber, ingestão de bebida (Hdt. 1, 172; Pla., Leg. 1, 637d e outros) lit. <span class=\"greek\">βρῶσις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πόσις</span> (<span class=\"greek\">βρῶσις</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:16</a>.</p><p class=\"entry-text\">② Aquilo que se bebe, bebida (Aeneas Tact. 589; Da 1:10; Philo, Op. M. 38), acerca do sangue de Jesus <span class=\"greek\">ἀληθής</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">πόσις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.55\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:55</a>.—DELG s.v. <span class=\"greek\">πίνω</span> C 4. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0295-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πόσος, η, ον</h1><div class=\"entry-meta\"><span>pronome interrogativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πόσος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (Aeschyl.+), pron. correlativo em perguntas diretas e indiretas.</p><p class=\"entry-text\">① Relativo a grau ou magnitude: como interrogativo ou exclamação, quão grande(?) no sing. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:28</a> D (indir.); 1 Cl 56:16 (indir.). <span class=\"greek\">πός</span>. <span class=\"greek\">χρόνος</span> <span class=\"greek\">ἐστίν</span>; há quanto tempo? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:21</a> (sobre <span class=\"greek\">πός</span>. <span class=\"greek\">χρόν</span>. cf. Soph., Oed. R. 558; Pla., Rep. 7, 546a; ApcMos 31; Just., D. 32, 4). Em uma exclamação (Appian, Mithrid. 58 §237 <span class=\"greek\">πόσην</span> <span class=\"greek\">ὠμότητα</span>, <span class=\"greek\">πόσην</span> <span class=\"greek\">ἀσέβειαν</span>—B-D-F §304; Rob. 741) <span class=\"greek\">πόσην</span> <span class=\"greek\">κατειργάσατο</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">σπουδήν</span> quanto zelo suscitou em vós! <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:11</a>; emprego pospositivo <span class=\"greek\">τὸ</span> <span class=\"greek\">σκότος</span> <span class=\"greek\">πόσον</span>; quão grandes devem ser as trevas? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:23</a>. <span class=\"greek\">πόσῳ</span>; em que grau? quanto? <span class=\"greek\">πόσῳ</span> <span class=\"greek\">διαφέρει</span> <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">προβάτου</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:12</a>. Seguido de um comp. (Polyaenus 3, 9, 25 <span class=\"greek\">πόσῳ</span> <span class=\"greek\">φοβερώτεροι</span>;) <span class=\"greek\">πόσῳ</span> <span class=\"greek\">δοκεῖτε</span> <span class=\"greek\">χείρονος</span> <span class=\"greek\">ἀξιωθήσεται</span> <span class=\"greek\">τιμωρίας</span>; de quanto maior punição julgais que alguém será digno? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:29</a>. <span class=\"greek\">πόσῳ</span> <span class=\"greek\">μᾶλλον</span>; quanto mais? (PFlor 170, 8 [III d.C.] <span class=\"greek\">εἰ</span> … <span class=\"greek\">πόσῳ</span> <span class=\"greek\">μᾶλλον</span>=se … quanto mais; Syntipas 19, 15; Jos., Bell. 2, 365; Diod S 1, 2, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:11</a>; 10:25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:13</a>; 12:24, 28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:14</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:12</a>, 24; Phlm 16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:14</a>; B 19:8; D 4:8; IEph 5:1f; 16:2; AcPl Cor 2:31. <span class=\"greek\">πόσῳ</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">οὐ</span>; quanto menos? (Ps.-Clem., Hom. 10, 20) 2 Cl 17:1.—JBonsirven, Exégèse rabbinique et exégèse paulinienne ’39; HMüller, Der rabbinische Qal-Wachomer-Schluss in paul. Typologie (Ro 5), ZNW 58, ’67, 73–92.</p><p class=\"entry-text\">② Relativo a quantidade: como interrogativo, quantos, quanto(?)</p><p class=\"entry-text\">ⓐ Com um substantivo no pl. (Aeschin. 2, 95; X., Mem. 1, 2, 35; 2 Km 19:35; ApcSed 8:7ff; Just., A I, 21, 2) <span class=\"greek\">πόσους</span> <span class=\"greek\">ἄρτους</span> <span class=\"greek\">ἔχετε</span>; quantos pães tendes? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:38</a>; 8:5. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:9</a>, 10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:19</a>, 20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:17</a> (exclam. como Ps 118:84); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:20</a> (Jos., Ant. 7, 318 <span class=\"greek\">πόσαι</span> <span class=\"greek\">μυριάδες</span> <span class=\"greek\">εἰσὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">λαοῦ</span>); 2 Cl 1:3.</p><p class=\"entry-text\">ⓑ Sem substantivo</p><p class=\"entry-text\"><span class=\"greek\">α</span>. No pl. <span class=\"greek\">πόσοι</span>; quantos? (TestBenj 3:4; Ps.-Clem., Hom. 9, 18; 10, 23) Hs 8, 6, 1.—<span class=\"greek\">πόσα</span>; quantas coisas? (TestJos 10:1; Ps.-Clem., Hom. 9, 18; Just., D. 85, 5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:4</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. No sing. <span class=\"greek\">πόσον</span>; quanto? (TestNapht 2:2 <span class=\"greek\">οἶδεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κεραμεὺς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σκεῦος</span> <span class=\"greek\">πόσον</span> <span class=\"greek\">χωρεῖ</span>; BGU 893, 26 <span class=\"greek\">ἐπύθετο</span>, <span class=\"greek\">πόσον</span> <span class=\"greek\">ἔχει</span>) <span class=\"greek\">πόσον</span> <span class=\"greek\">ὀφείλεις</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:5</a>, 7.—DELG s.v. <span class=\"greek\">πο</span>-. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0295-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποσότης, ητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποσότης</span>, <span class=\"greek\">ητος</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πόσος</span>; Aristot., Metaph. 1028a, 19; Polyb. 16, 12, 10 e outros; inscrições, papiros, Philo), qualidade de grandeza em grau ou número, quantidade, montante, com <span class=\"greek\">καλλονή</span> 1 Cl 35:3. <span class=\"greek\">συνοψίσας</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">π</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">δαπάνης</span> estimando o montante da despesa Hs 5, 3, 7.—DELG s.v. <span class=\"greek\">πο</span>-.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0295-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποταμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποταμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (Hom.+), rio, corrente</p><p class=\"entry-text\">ⓐ Lit., acerca do Jordão (Jos., Ant. 20, 97, Vi. 399; SibOr 6, 5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:5</a>. Acerca do Eufrates (v. <span class=\"greek\">Εὐφράτης</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:14</a>; 16:12. Acerca do Tibre (SibOr 5, 170; Just., A I, 26, 2) Hv 1, 1, 2ab; mas o <span class=\"greek\">ποταμός</span> de 1, 1, 3 não pode ser identificado (cf. Hdb. ad loc.). <span class=\"greek\">ἦν</span> <span class=\"greek\">π</span>. <span class=\"greek\">ἕλκων</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">δεξιῶν</span> (<span class=\"greek\">ἕλκω</span> 3) B 11:10. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:10</a>; 12:15f; 16:4. <span class=\"greek\">ἐπέβλεψα</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">χείμαρρον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ποταμοῦ</span> observei o fluxo do rio GJs 18:3 (códices).—Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:48f</a> <span class=\"greek\">ὁ</span> <span class=\"greek\">ποταμός</span> significa um rio que corre continuamente perto da casa em questão, mas no paralelo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:25</a>, 27 <span class=\"greek\">οἱ</span> <span class=\"greek\">ποταμοί</span> devem ser entendidos como torrentes montanhosas ou torrentes de inverno que surgem nas ravinas após uma chuva intensa e arrastam tudo diante de si (assim o pl. em Heraclit. Sto. 38 p. 55, 9; Quint. Smyrn. [400 d.C.] 8, 384; 14, 5). O rio de água viva na Jerusalém celestial <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:1</a>; cf. v. 2. Em um contexto fragmentário AcPl BMM verso 15.</p><p class=\"entry-text\">ⓑ O pl. acerca de grandes quantidades de água corrente. Fig. <span class=\"greek\">ποταμοὶ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κοιλίας</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ῥεύσουσιν</span> <span class=\"greek\">ὕδατος</span> <span class=\"greek\">ζῶντος</span> correntes de água viva fluirão de seu corpo (do Redentor—v. <span class=\"greek\">κοιλία</span> 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:38</a> (citação das Escrituras de origem desconhecida. V. Hdb. ad loc.; Bultmann 229, 2; LKöhler, Kleine Lichter ’45, 39–41; CGoodwin, JBL 63, ’54, 72f).—B. 42. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0295-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποταμοφόρητος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποταμοφόρητος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">φορητός</span> ‘levado, transportado’ [<span class=\"greek\">φέρω</span>]; PAmh 85, 16 [78 d.C.]; PTebt 610; PStras 5, 10; PFlor 368, 12 e outros em papiros), relativo a ser levado involuntariamente por uma corrente de água, arrastado por um rio, submerso por uma torrente <span class=\"greek\">ἵνα</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">π</span>. <span class=\"greek\">ποιήσῃ</span> para que a arrastasse com a corrente, isto é, a afogasse <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:15</a>.—AWikenhauser, BZ 6, 1908, 171; 7, 1909, 48. —DELG s.v. <span class=\"greek\">φέρω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0295-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποταπός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo interrogativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποταπός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span>, substituto do mais antigo <span class=\"greek\">ποδαπός</span> (este último ocorre em Aeschyl., X., Pla.+; Jos., Bell. 4, 169, Ant. 6, 345; assim D <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:29</a>; 7:39; v. Lob., Phryn. p. 56f; Schwyzer I 604, 1), mas somente no sentido atestável para <span class=\"greek\">ποδαπός</span> (Demosth.+), referência interrogativa a classe ou espécie, de que tipo ou espécie(?) (Dionys. Hal.; Lucian; ApcSed 7:1; Philo; Jos., Bell. 2, 32, C. Ap. 1, 255 e outros; POxy 1678, 16 [III d.C.]; Sus 54 LXX; B-D-F §298, 3; Rob. 741), acerca de pessoas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:11</a>; Hs 8, 6, 3. <span class=\"greek\">τίς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ποταπὴ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">γυνή</span> quem é e que espécie de mulher é <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:39</a> (cf. Jos., Ant. 7, 72 e a formulação afim <span class=\"greek\">εἰς</span> <span class=\"greek\">τίνα</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ποῖον</span> <span class=\"greek\">καιρόν</span> ‘para que tempo ou que espécie de tempo’ <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:11</a> [v. <span class=\"greek\">καιρός</span> 1a]). <span class=\"greek\">ποταποὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">μορφήν</span> que tipo de aparência têm ApcPt 2:5.—<span class=\"greek\">ποταπός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">εἰδέᾳ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Παῦλος</span> qual era a aparência de Paulo AcPl Ant 13, 13–15 (=Aa I 237, 2). Acerca de coisas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:29</a>; Hv 3, 4, 3; Hs 4:3; 6, 3, 4. Às vezes o contexto exige o sentido quão grande, quão maravilhoso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:1ab</a>; quão glorioso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:1</a>.—Em <span class=\"greek\">ποταπαὶ</span> … <span class=\"greek\">εἰσὶν</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">πονηρίαι</span>; Hm 8:3 <span class=\"greek\">ποταπαί</span>=<span class=\"greek\">τίνες</span>: quais são os vícios?—DELG s.v. <span class=\"greek\">πο</span>-B4. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0295-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποταπῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποταπῶς</span> adv. de <span class=\"greek\">ποταπός</span> (v. esse lema), de que maneira, como(?) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:18</a> D.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0295-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πότε</h1><div class=\"entry-meta\"><span>advérbio interrogativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πότε</span> adv. interrog. de tempo (Hom.+), quando(?) predominantemente em perguntas diretas, mas também em indiretas: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:3</a> (talvez indir.); 25:37–39, 44; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:4</a> (talvez indir.), 33 (indir.), 35 (indir.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:36</a> (indir.); 17:20 (indir.); 21:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:25</a>; 2 Cl 12:2 (indir.; dito apócrifo de Jesus); B 12:1 (citação profética de origem incerta); Hv 1, 1, 7; 3, 6, 6; AcPl Ha 6, 17. Elíptico (indir.) <span class=\"greek\">εἴρηκεν</span> <span class=\"greek\">πότε</span> disse(-nos) quando (acontecerá) B 6:19. <span class=\"greek\">ἕως</span> <span class=\"greek\">π</span>.; (LXX; ApcSed 12:1.—Jos., Ant. 2, 309 <span class=\"greek\">ἄχρι</span> <span class=\"greek\">π</span>.) por quanto tempo?, lit. até quando? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:17ab</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:19ab</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:10</a>; GJs 2:2; Hv 3, 6, 5. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">πότε</span> desde quando <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:2</a> D (B-D-F §203).—DELG s.v. <span class=\"greek\">πο</span>-A. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0295-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποτέ</h1><div class=\"entry-meta\"><span>partícula enclítica</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποτέ</span> partícula enclítica (Hom. et al.; papiros, LXX, TestSol, TestAbr,TestJob, JosAs, GrBar; ApcEsdr 4:33 p. 29, 9 Tdf.; ApcMos; apologistas [Mel., P. 37, 253 e outros])</p><p class=\"entry-text\">① Relativo à generalização do tempo, em algum momento do passado, outrora, antigamente (Jos., Bell. 7, 112; Mel.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:9</a>; 11:30 (sobre <span class=\"greek\">ποτὲ</span> … <span class=\"greek\">νῦν</span> [<span class=\"greek\">νυνί</span>] <span class=\"greek\">δέ</span>, v. <span class=\"greek\">νῦν</span> 1a<span class=\"greek\">β</span>ג); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:13</a>, 23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:2f</a> e outros; B 7:9; MPol 8:1; EpilMosq 3; Papias (2:3).—Acerca do futuro (Appian, Bell. Civ. 3, 63 §257=finalmente; Jos., Bell. 5, 19; Just., D. 65, 2) <span class=\"greek\">σύ</span> <span class=\"greek\">ποτε</span> <span class=\"greek\">ἐπιστρέψας</span> quando tiveres retornado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:32</a>; Hm 9, 7.—<span class=\"greek\">ποτὲ</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ποτὲ</span> <span class=\"greek\">δέ</span> ora … ora, às vezes … às vezes (X., Mem. 4, 2, 32; Pla., Theaet. 170c; Diod S 1, 32, 2; 2, 59, 5; Wsd 16:18f; TestSol; GrBar 3:5; ApcEsdr 4:33; Ar. 7, 2; Just., A I, 14, 1 e outros) B 10:7; GJs 17:2. Finalmente, por fim MPol 8:1. Sobre <span class=\"greek\">ἤδη</span> <span class=\"greek\">ποτέ</span> agora finalmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:10</a>; 2 Cl 13:1, v. <span class=\"greek\">ἤδη</span> 2.—Depois de negativas, alguma vez <span class=\"greek\">οὐ</span> … <span class=\"greek\">ποτέ</span> não … alguma vez, nunca <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:21</a>; AcPlCor 1:4. <span class=\"greek\">οὔτε</span> … <span class=\"greek\">ποτὲ</span> … <span class=\"greek\">οὔτε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:5</a>; IRo 2:1. MPol 17:2. <span class=\"greek\">μήτε</span> … <span class=\"greek\">ποτὲ</span> B 16:10. <span class=\"greek\">οὐδείς</span> <span class=\"greek\">ποτε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:29</a> (X., Mem. 1, 4, 19 <span class=\"greek\">μηδέν</span> <span class=\"greek\">ποτε</span>). <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> … <span class=\"greek\">ποτέ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:10</a>. Sobre <span class=\"greek\">μή</span> <span class=\"greek\">ποτε</span>, v. <span class=\"greek\">μήποτε</span>; sobre <span class=\"greek\">δή</span> <span class=\"greek\">ποτε</span>, v. <span class=\"greek\">δήποτε</span>. Em perguntas retóricas que esperam resposta negativa <span class=\"greek\">τίς</span> … <span class=\"greek\">ποτέ</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:7</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:5</a>, 13; Dg 8:1.</p><p class=\"entry-text\">② Indicando uma suposição, presumivelmente <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">φιλοξενίᾳ</span> <span class=\"greek\">εὑρίσκεται</span> <span class=\"greek\">ἀγαθοποίησίς</span> <span class=\"greek\">ποτε</span> Hm 8:10. Cf. Hs 6, 5, 4 v.l.</p><p class=\"entry-text\">③ Relativo a generalizar, quer que seja, depois de relativos (<span class=\"greek\">ὅπου</span> <span class=\"greek\">ποτέ</span> Just., D., 127, 2) <span class=\"greek\">ὅσοι</span> <span class=\"greek\">ποτέ</span> quaisquer, quem quer que seja Hs 9, 6, 7; 9, 28, 3. Sobre <span class=\"greek\">ὁποῖοί</span> <span class=\"greek\">ποτε</span> <span class=\"greek\">ἦσαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:6</a>, v. <span class=\"greek\">ὁποῖος</span> e cf. Epict. 2, 20, 5 <span class=\"greek\">τίνες</span> <span class=\"greek\">ποτέ</span>; <span class=\"greek\">οἱ</span> <span class=\"greek\">Ἀκαδημαϊκοὺς</span> <span class=\"greek\">αὑτοὺς</span> <span class=\"greek\">λέγοντες</span>=quem são, então? Aqueles que se chamam acadêmicos? Demetr.: 722 Fgm. 1, 14 <span class=\"greek\">διὰ</span> <span class=\"greek\">τί</span> <span class=\"greek\">ποτε</span>; ‘por que, afinal?’—Sobre <span class=\"greek\">τί</span> <span class=\"greek\">δή</span> <span class=\"greek\">ποτε</span> Dg 1, v. <span class=\"greek\">δήποτε</span>.—DELG s.v. <span class=\"greek\">πο</span>-A. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0295-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πότερος, α, ον</h1><div class=\"entry-meta\"><span>pronome interrogativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πότερος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> (Hom.+), em nossa literatura (e na LXX, mas somente em Job; Thackeray p. 192) somente na forma fixa <span class=\"greek\">πότερον</span> como palavra interrog. (B-D-F §64, 6; 298, 1; Rob. 741; 1177), se: em uma pergunta disjuntiva <span class=\"greek\">πότερον</span> … <span class=\"greek\">ἤ</span> se … ou se (Pind.; X., Mem. 2, 7, 4; Appian, Bell. Civ. 3, 53 §220; SIG 977, 24–29 <span class=\"greek\">ἐπερωτᾷ</span> … <span class=\"greek\">πότερον</span> … <span class=\"greek\">ἤ</span>; cf. 987, 14–19; PTebt 289, 6 [23 d.C.]; Job 7:12; Jos., Ant. 6, 71, C. Ap. 2, 120; Tat. 21, 2; Ath. 26, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:17</a>; B 19:5; D 4:4; Hs 9, 28, 4.—DELG s.v. <span class=\"greek\">πο</span>-B 4. M-M s.v. <span class=\"greek\">πότερον</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0295-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποτήριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποτήριον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (dim. de <span class=\"greek\">ποτήρ</span> [<span class=\"greek\">πίνω</span>]; Alcaeus, Sappho, Hdt.+), recipiente usado para beber, copo, cálice (na literatura grega principalmente para beber vinho)</p><p class=\"entry-text\">ⓐ Lit. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:25f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:4</a>, 8 v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:39</a>. <span class=\"greek\">π</span>. <span class=\"greek\">χρυσοῦν</span> (ChronLind B, 42) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:4</a> (v. sobre <span class=\"greek\">πόρνη</span> 2). Com gen. de seu conteúdo: <span class=\"greek\">π</span>. <span class=\"greek\">ὕδατος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:41</a> (Just., D. 65, 3; 66, 4). <span class=\"greek\">π</span>. <span class=\"greek\">ψυχροῦ</span> um copo de água fria <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:42</a> (sobre a elipse, v. B-D-F §241, 7; Rob. 1202). Frequentemente na linguagem da Eucaristia <span class=\"greek\">λαβὼν</span> <span class=\"greek\">ποτήριον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:23</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:17</a>, 20a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:25a</a>; IPhld 4; D 9:2.—O cálice representa, por metonímia, aquilo que contém (Pr 23:31) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:20b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:25b</a>, 26 (<span class=\"greek\">τὸ</span> <span class=\"greek\">ποτ</span>. corresponde a <span class=\"greek\">τὸν</span> <span class=\"greek\">ἄρτον</span>).—<span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ποτηρίου</span> <span class=\"greek\">πίνειν</span> v. 28 (Alcaeus 34 D.2). <span class=\"greek\">τὸ</span> <span class=\"greek\">ποτήριον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">εὐλογίας</span> (JosAs 8:11; v. <span class=\"greek\">εὐλογία</span> 3b<span class=\"greek\">β</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:16</a>. Com gen. da pessoa que concede a bebida (<span class=\"greek\">τὸ</span>) <span class=\"greek\">ποτήριον</span> (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">κυρίου</span> <span class=\"greek\">πίνειν</span> v. 21a; 11:27. Oposto a <span class=\"greek\">ποτήριον</span> <span class=\"greek\">δαιμονίων</span> 10:21b (FDölger, D. Kelch der Dämonen: Ac IV 266–70).</p><p class=\"entry-text\">ⓑ Fig. (no AT <span class=\"greek\">ποτήριον</span> é uma expressão para destino tanto em bom como em mau sentido, para a morte em geral TestAbr A 1 e outros. Sobre o conceito de beber um cálice de sofrimento, cf. Is 51:17, 22; La 4:21; Ps 10:6; 74:9.—WLotz, D. Sinnbild des Bechers: NKZ 28, 1917, 396–407; F-JLeenhardt, Le Sacrement de la Sainte Cène ’48, 43–45), acerca de sofrer uma morte violenta; primeiramente do próprio Cristo <span class=\"greek\">τὸ</span> <span class=\"greek\">ποτήριον</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">δέδωκέν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">πίω</span> <span class=\"greek\">αὐτό</span>; não beberei o cálice que o Pai me deu? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:11</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:22</a>; 26:39, 42 v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:38</a>; 14:36 (Cranfield, ET 59, ’47/48, 137f; DDaube, A Prayer Pattern in Judaism, Studia Evangelica 73, ’59, 539–45); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:42</a>. Acerca do martírio de Pedro <span class=\"greek\">πίε</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ποτήριον</span> … <span class=\"greek\">ἐν</span> <span class=\"greek\">χειροῖν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Ἅιδου</span> bebe o cálice das mãos do filho, (que está) no Hades ApcPt Rainer 16–18 (sobre a questão da identidade do <span class=\"greek\">υἱός</span>, v. os comentários de Ja. p. 274). O martírio de um cristão é correspondentemente descrito como <span class=\"greek\">λαβεῖν</span> <span class=\"greek\">μέρος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ποτηρίῳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> participar do cálice de Cristo MPol 14:2. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:39</a> (v. sobre estas passagens ESchwartz, Über den Tod der Söhne Zebedaei: GGAbh. n.s. VII/5, 1904, NGG 1907, 266ff, ZNW 11, 1910, 89–104; FSpitta, ibid. 39–58; CBruston, RTQR 19, 1910, 338–44, RHPR 5, 1925, 69–71; VWeber, Der Katholik 92, 1912, 434–45; JBernard, ET 39, 1928, 456–58).—Sobre <span class=\"greek\">τὸ</span> <span class=\"greek\">ποτήριον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οἴνου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θυμοῦ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὀργῆς</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:19</a>, v. <span class=\"greek\">θυμός</span> 1 e 2. Sobre as passagens a ele relacionadas, isto é, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:10</a>; 18:6, v. <span class=\"greek\">κεράννυμι</span> 1.—B. 348. DELG s.v. C 7. M-M. EDNT. TW.</p></section></article>"};
